import{_ as i,a as e,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const F=JSON.parse('{"title":"Kubernetes 升级与维护","description":"集群升级、版本兼容、备份、驱逐与回退","frontmatter":{"title":"Kubernetes 升级与维护","description":"Kubernetes 版本偏差、升级顺序、备份验证、节点维护、kubeadm 与托管集群注意事项","sources":[{"repository":"TeamDocs","file":"docs/engineering/kubernetes/16-upgrade-maintenance.md"}],"showdocs":{"topics":[{"id":"kubernetes","title":"Kubernetes","link":"/topics/kubernetes/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Kubernetes 系统教程","summary":"集群升级、版本兼容、备份、驱逐与回退","status":"active","related":[{"title":"Kubernetes 操作与命令","link":"/systems/kubernetes/plus/ecosystem/kubernetes-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储","link":"/systems/kubernetes/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · 按 Pod、Service 与端点定位故障至Pod 运行但服务不可达的复盘","link":"/systems/kubernetes/troubleshooting-part-02","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes 排障：Pod、发布、网络与存储 · Kubernetes 排障手册","link":"/systems/kubernetes/troubleshooting-part-01","kind":"故障排查","scope":"general","audience":"general"},{"title":"Kubernetes：部署配置、服务身份与持久卷","link":"/systems/kubernetes/plus/practice/application","kind":"实践","scope":"general","audience":"general"}],"prev":{"text":"Kubernetes 可观测性：指标、日志与事件","link":"/systems/kubernetes/observability"},"next":{"text":"kubectl 常用命令与操作边界","link":"/systems/kubernetes/commands"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Kubernetes 可观测性：指标、日志与事件","link":"/systems/kubernetes/observability"},"next":{"text":"kubectl 常用命令与操作边界","link":"/systems/kubernetes/commands"}},"headers":[],"relativePath":"systems/kubernetes/plus/subjects/16-upgrade-maintenance.md","filePath":"systems/kubernetes/plus/subjects/16-upgrade-maintenance.md"}'),n={name:"systems/kubernetes/plus/subjects/16-upgrade-maintenance.md"};function l(k,s,h,r,p,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="kubernetes-升级与维护" tabindex="-1">Kubernetes 升级与维护 <a class="header-anchor" href="#kubernetes-升级与维护" aria-label="Permalink to &quot;Kubernetes 升级与维护&quot;">​</a></h1><h2 id="升级原则" tabindex="-1">升级原则 <a class="header-anchor" href="#升级原则" aria-label="Permalink to &quot;升级原则&quot;">​</a></h2><ul><li>只升级到上游和发行版/云厂商共同支持的版本。</li><li>次要版本逐级升级，不能跳过；先把当前分支升到最新补丁，再升目标分支最新补丁。</li><li>控制面先于 kubelet；组件偏差必须符合<a href="https://kubernetes.io/releases/version-skew-policy/" target="_blank" rel="noopener noreferrer">官方版本偏差策略</a>。</li><li>集群升级不等于只升级核心：CNI、CSI、Ingress/Gateway、DNS、Metrics、Operator、CRD 和客户端都有兼容矩阵。</li><li>先演练、备份和验证恢复，再变更；明确停止条件和回退/前滚策略。</li></ul><p>截至 2026-08-12，上游维护 1.36、1.35、1.34，最新稳定补丁为 v1.36.3。执行时重新核对 <a href="https://kubernetes.io/releases/" target="_blank" rel="noopener noreferrer">Releases</a>、<a href="https://dl.k8s.io/release/stable.txt" target="_blank" rel="noopener noreferrer"><code>stable.txt</code></a> 和供应商公告。</p><h2 id="升级前清单" tabindex="-1">升级前清单 <a class="header-anchor" href="#升级前清单" aria-label="Permalink to &quot;升级前清单&quot;">​</a></h2><ol><li>阅读目标次要版发布公告、完整 Changelog、Urgent Upgrade Notes、弃用/移除和已知问题。</li><li>盘点 API 使用：清单、Helm Chart、CRD、Webhook、Operator、客户端库。</li><li>核对所有插件和云服务兼容矩阵，升级必要的前置组件。</li><li>当前集群健康：API/etcd、节点、系统 Pod、存储、网络和备份无未解决告警。</li><li>容量足够逐节点 drain、Deployment surge 和故障域冗余；PDB 不会无解阻塞。</li><li>保存配置和资源清单；对 etcd/持久数据执行可恢复备份，并在隔离环境验证。</li><li>在接近生产的预发环境运行安装、升级、回滚/前滚、冒烟和性能测试。</li><li>通知业务、值班和供应商，设置变更窗口、观察期、负责人和停止条件。</li></ol><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wide</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --field-selector=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;status.phase!=Running&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apiservices</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/readyz?verbose&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span></code></pre></div><p>API 弃用扫描可使用组织批准的工具和 API Server 审计/指标；不要仅搜索 Git，因为运行中的 CR、Webhook 和外部客户端也可能调用旧 API。</p><h2 id="上游支持的组件顺序" tabindex="-1">上游支持的组件顺序 <a class="header-anchor" href="#上游支持的组件顺序" aria-label="Permalink to &quot;上游支持的组件顺序&quot;">​</a></h2><p>从 1.35 升 1.36 的通用顺序：</p><ol><li>所有 API Server 升到目标版本（HA 逐实例，混合期最多差一版）。</li><li>controller-manager、scheduler、cloud-controller-manager 升级。</li><li>kubelet 逐节点 drain 后升级；次要版 kubelet 不支持不驱逐 Pod 的原地升级。</li><li>kube-proxy 升级。</li></ol><p>kubectl 和客户端需保持在 API Server 前后一个次要版本内。这是组件兼容顺序，不是发行版命令；具体流程以厂商文档为准。</p><h2 id="节点维护-cordon、drain、uncordon" tabindex="-1">节点维护：cordon、drain、uncordon <a class="header-anchor" href="#节点维护-cordon、drain、uncordon" aria-label="Permalink to &quot;节点维护：cordon、drain、uncordon&quot;">​</a></h2><p>先确认节点上的 Pod、PDB 和本地数据：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;worker-01&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --field-selector=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spec.nodeName=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wide</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cordon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-daemonsets</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delete-emptydir-data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=20m</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 完成维护并验证节点健康后</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uncordon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">drain 参数</p><p><code>--delete-emptydir-data</code> 会删除该节点被驱逐 Pod 的 <code>emptyDir</code> 数据；应用必须把它视为临时数据。不要默认加 <code>--disable-eviction</code>，它绕过 PDB。带非控制器 Pod、Local PV 或特殊系统 Pod 的节点要用专用 Runbook。</p></div><p>逐节点操作，每步等待业务副本 Ready、错误率/延迟恢复后再继续。故障域内不要同时 drain 过多节点。</p><h2 id="kubeadm-集群" tabindex="-1">kubeadm 集群 <a class="header-anchor" href="#kubeadm-集群" aria-label="Permalink to &quot;kubeadm 集群&quot;">​</a></h2><p>kubeadm 通常先在第一个控制面节点升级 kubeadm 并运行 <code>kubeadm upgrade plan/apply</code>，再处理其余控制面和逐节点 drain 后的 kubelet。包 hold/unhold、配置 API 和准确命令必须使用目标版本的 <a href="https://kubernetes.io/docs/tasks/administer-cluster/kubeadm/kubeadm-upgrade/" target="_blank" rel="noopener noreferrer">kubeadm 升级指南</a>，不得照抄旧教程；外部 etcd 与 stacked etcd 的流程也不同。</p><h2 id="托管集群" tabindex="-1">托管集群 <a class="header-anchor" href="#托管集群" aria-label="Permalink to &quot;托管集群&quot;">​</a></h2><ul><li>核对控制面与节点池可选版本、强制升级日期和 EOL。</li><li>阅读供应商变更：OS 镜像、运行时、CNI/CSI、LB、身份、自动修复。</li><li>先升控制面，再滚动新节点池；高风险升级可新建节点池迁移工作负载。</li><li>回退控制面通常不被支持，要以修复/前滚为主要方案。</li></ul><h2 id="etcd-备份与恢复" tabindex="-1">etcd 备份与恢复 <a class="header-anchor" href="#etcd-备份与恢复" aria-label="Permalink to &quot;etcd 备份与恢复&quot;">​</a></h2><p>etcd 快照必须来自一致、受支持的端点，包含正确证书，并加密保存到独立故障域。备份成功日志不代表可恢复：</p><ul><li>记录 Kubernetes/etcd 版本、集群 ID、证书和加密配置依赖。</li><li>定期在隔离环境恢复，验证 API 对象和关键控制器。</li><li>恢复是集群级灾难操作，所有 API Server/etcd 成员必须按一致流程处理。</li><li>恢复旧快照会回退 Kubernetes API 状态，但不会自动回退外部云资源和业务数据库。</li></ul><p>不要在通用文档中复制带生产证书路径的 <code>etcdctl</code> 命令；按集群拓扑的灾备 Runbook 执行。</p><h2 id="升级中观察" tabindex="-1">升级中观察 <a class="header-anchor" href="#升级中观察" aria-label="Permalink to &quot;升级中观察&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wide</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raw=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/readyz?verbose&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apiservices</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --field-selector=type=Warning</span></span></code></pre></div><p>同时监控用户成功率/延迟、API Server、etcd、调度、DNS、CNI/CSI、Ingress、Webhook、Pending、重启和 PDB。停止条件应是可量化阈值，而非“感觉异常”。</p><h2 id="升级后验证" tabindex="-1">升级后验证 <a class="header-anchor" href="#升级后验证" aria-label="Permalink to &quot;升级后验证&quot;">​</a></h2><ul><li>所有节点和控制面版本、运行时版本符合计划，无长期偏差。</li><li>系统组件、扩展 API、Webhook、CRD Controller 和插件 Ready。</li><li>创建/更新/删除测试工作负载，验证调度、DNS、Service、Ingress/Gateway、NetworkPolicy 和存储挂载。</li><li>执行应用冒烟、Job、HPA、日志/指标/告警和备份测试。</li><li>检查废弃 API 调用、新 Warning、审计和资源使用变化。</li><li>保留观察期，完成变更记录和新基线快照。</li></ul><h2 id="回退边界" tabindex="-1">回退边界 <a class="header-anchor" href="#回退边界" aria-label="Permalink to &quot;回退边界&quot;">​</a></h2><p>工作负载镜像通常可回滚，但 Kubernetes 控制面/etcd 降级一般不受支持；API 存储转换、组件状态和外部控制器可能已经前进。升级计划必须优先设计安全前滚。若达到停止条件，暂停后续节点、隔离问题、保留证据，并调用发行版支持流程，不擅自降级二进制或恢复旧 etcd。</p>`,32)])])}const c=i(n,[["render",l]]);export{F as __pageData,c as default};
